import styled from '@emotion/styled';
import { styled as hexauiStyled } from '@hexa-ui/theme';
import { STICKY_NAVIGATION_TOP_OFFSET_FALLBACK_PX } from 'hooks/useStickyNavigationTopOffset/constants';

interface StyledPerformanceSectionHeaderProps {
  stickyHeader?: boolean;
  stickyTopOffset?: string;
}

export const StyledPerformanceSectionHeader = styled('div', {
  shouldForwardProp: (prop) =>
    prop !== 'stickyHeader' && prop !== 'stickyTopOffset',
})<StyledPerformanceSectionHeaderProps>`
  display: flex;
  flex-direction: column;
  justify-content: flex-start;
  align-items: flex-start;
  gap: 12px;
  background: white;
  padding: 21px 24px;
  border-bottom: 1px solid #14141429;
  margin: -24px -24px 0 -24px;
  border-radius: 16px 16px 0 0;

  ${({ stickyHeader, stickyTopOffset }) =>
    stickyHeader &&
    `
      position: sticky;
      top: ${stickyTopOffset ?? `${STICKY_NAVIGATION_TOP_OFFSET_FALLBACK_PX}px`};
      z-index: 20;
      isolation: isolate;
      border-top: none;

      &::after {
        content: '';
        position: absolute;
        left: -1px;
        right: -1px;
        top: 0;
        height: 24px;
        background:
          radial-gradient(
            circle at 17px 17px,
            transparent 0 17px,
            #f7f4ef 17.5px 100%
          ) left top / 18px 18px no-repeat,
          radial-gradient(
            circle at calc(100% - 17px) 17px,
            transparent 0 17px,
            #f7f4ef 17.5px 100%
          ) right top / 18px 18px no-repeat,
          linear-gradient(#f7f4ef, #f7f4ef) left 18px / 2px 0px no-repeat,
          linear-gradient(#f7f4ef, #f7f4ef) right 18px / 2px 0px no-repeat;
        pointer-events: none;
      }
    `}
`;

export const StyledPerformanceSectionHeaderTopRow = styled.div`
  display: flex;
  align-items: center;
  gap: 8px;
`;

export const StyledSectionsContainer = hexauiStyled('div', {
  display: 'flex',
  flexDirection: 'column',
  gap: '24px',
  position: 'relative',
  zIndex: 0,
});
